<script>
  // Quick Interaction Handlers
  const scanBtn = document.getElementById('btn-scan');
  const paymentModal = document.getElementById('payment-modal');

  if (scanBtn) {
    scanBtn.addEventListener('click', () => {
      window.location.href = "{{ route('scanner') }}";
    });
  }

  function showPaymentModal() {
    paymentModal.classList.remove('hidden');
    paymentModal.classList.add('flex');
  }

  function closePaymentModal() {
    paymentModal.classList.add('hidden');
    paymentModal.classList.remove('flex');
  }

  function renewBook(button) {
    button.disabled = true;
    button.innerHTML = '<span class="material-symbols-outlined text-[16px] animate-spin">refresh</span> Memproses...';
    
    setTimeout(() => {
      button.className = 'bg-surface-container-high text-on-surface-variant px-space-md py-2 rounded-lg font-label-md text-label-md flex items-center gap-1.5 cursor-not-allowed';
      button.innerHTML = '<span class="material-symbols-outlined text-[16px] text-secondary">check</span> Diperpanjang';
      
      const parentCard = button.closest('article');
      const badge = parentCard.querySelector('.bg-secondary-fixed');
      if (badge) {
        badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-secondary"></span> Tenggat: 25 Nov 2024';
      }
    }, 600);
  }

  function simulateScanSuccess() {
    closeScannerModal();
    alert('Buku berhasil terdeteksi: Kimia Organik Vol. 2! Silakan konfirmasi di meja checkout.');
